  @Test
  public void testCompareTo() {
    // Arrange
    AccountCapsule accountCapsule = new AccountCapsule(Protocol.Account.getDefaultInstance());

    // Act and Assert
    assertEquals(0, accountCapsule.compareTo(new AccountCapsule(Protocol.Account.getDefaultInstance())));
  }

