    assertEquals((byte) 1, actualData[22]);
    assertEquals((byte) 1, actualData[54]);
    assertEquals((byte) 1, actualData[68]);
    assertEquals((byte) 26, actualData[23]);
    assertEquals((byte) 26, actualData[3]);
    assertEquals((byte) 2, actualData[13]);
    assertEquals((byte) 2, actualData[17]);
    assertEquals((byte) 2, actualData[66]);
    assertEquals((byte) 2, actualData[70]);
    assertEquals((byte) 5, actualData[4]);
    assertEquals(72, actualData.length);
    assertEquals((byte) 7, actualData[24]);
    assertEquals(' ', actualData[10]);
    assertEquals(' ', actualData[53]);
    assertEquals('*', actualData[71]);
    assertEquals('2', actualData[55]);
    assertEquals(':', actualData[12]);
    assertEquals(':', actualData[65]);
    assertEquals('A', actualData[57]);
    assertEquals('A', actualData[59]);
    assertEquals('A', actualData[61]);
    assertEquals('A', actualData[63]);
    assertEquals('X', actualData[58]);
    assertEquals('X', actualData[60]);
    assertEquals('X', actualData[62]);
    assertEquals('X', actualData[Double.SIZE]);
    assertEquals('\b', actualData[19]);
    assertEquals('\b', actualData[56]);
    assertEquals('\r', actualData[2]);
    assertEquals('a', actualData[47]);
    assertEquals('c', actualData[48]);
    assertEquals('e', actualData[52]);
    assertEquals('e', actualData[8]);
    assertEquals('i', actualData[50]);
    assertEquals('n', actualData[7]);
    assertEquals('o', actualData[5]);
    assertEquals('r', actualData[9]);
    assertEquals('t', actualData[49]);
    assertEquals('v', actualData[51]);
    assertEquals('w', actualData[6]);
