  /**
   * Method under test: {@link AccountCapsule#getAddress()}
   */
  @Test
  public void testGetAddress() {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    ByteString actualAddress = accountCapsule.getAddress();

    // Assert
    ByteString byteString = actualAddress.EMPTY;
    Descriptors.Descriptor descriptorForType = accountCapsule.getAccountResource().getDescriptorForType();
    assertEquals(byteString, descriptorForType.toProto().getDefaultInstanceForType().getNameBytes());
    DescriptorProtos.FileOptions options = descriptorForType.getFile().getOptions();
    assertEquals(byteString, options.getCsharpNamespaceBytes());
    assertEquals(byteString, options.getObjcClassPrefixBytes());
    assertEquals(byteString, options.getPhpClassPrefixBytes());
    assertEquals(byteString, options.getPhpMetadataNamespaceBytes());
    assertEquals(byteString, options.getPhpNamespaceBytes());
    assertEquals(byteString, options.getRubyPackageBytes());
    assertEquals(byteString, options.getSwiftPrefixBytes());
    assertSame(account, accountCapsule.getInstance());
    assertSame(byteString, accountCapsule.getAccountId());
    assertSame(byteString, accountCapsule.getAccountName());
    assertSame(byteString, actualAddress);
    assertSame(byteString, accountCapsule.getAssetIssuedID());
    assertSame(byteString, accountCapsule.getAssetIssuedName());
  }

