  /**
   * Method under test: {@link AccountCapsule#addAsset(byte[], long)}
   */
  @Test
  public void testAddAsset() throws UnsupportedEncodingException {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    boolean actualAddAssetResult = accountCapsule.addAsset("AXAXAXAX".getBytes("UTF-8"), 42L);

    // Assert
    Protocol.Account instance = accountCapsule.getInstance();
    assertEquals(1, instance.getAllFields().size());
    Map<String, Long> assetMap = accountCapsule.getAssetMap();
    assertEquals(1, assetMap.size());
    Map<String, Long> assetMapForTest = accountCapsule.getAssetMapForTest();
    assertEquals(1, assetMapForTest.size());
    Map<String, Long> asset = instance.getAsset();
    assertEquals(1, asset.size());
    Map<String, Long> assetMap2 = instance.getAssetMap();
    assertEquals(1, assetMap2.size());
    assertEquals(1, instance.getAssetCount());
    assertEquals(14, instance.getSerializedSize());
    assertEquals(42L, assetMap.get("AXAXAXAX").longValue());
    assertEquals(42L, assetMapForTest.get("AXAXAXAX").longValue());
    assertEquals(42L, asset.get("AXAXAXAX").longValue());
    assertEquals(42L, assetMap2.get("AXAXAXAX").longValue());
    assertTrue(actualAddAssetResult);
    assertSame(account, instance.getDefaultInstanceForType());
    assertArrayEquals(new byte[]{'2', '\f', '\n', '\b', 'A', 'X', 'A', 'X', 'A', 'X', 'A', 'X', 16, '*'},
        accountCapsule.getData());
  }

