  @Test
  public void testPutLatestAssetOperationTimeMap() {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    accountCapsule.putLatestAssetOperationTimeMap("Key", 42L);

    // Assert
    Protocol.Account instance = accountCapsule.getInstance();
    assertEquals(1, instance.getAllFields().size());
    Map<String, Long> latestAssetOperationTimeMap = accountCapsule.getLatestAssetOperationTimeMap();
    assertEquals(1, latestAssetOperationTimeMap.size());
    Map<String, Long> latestAssetOperationTime = instance.getLatestAssetOperationTime();
    assertEquals(1, latestAssetOperationTime.size());
    Map<String, Long> latestAssetOperationTimeMap2 = instance.getLatestAssetOperationTimeMap();
    assertEquals(1, latestAssetOperationTimeMap2.size());
    assertEquals(1, instance.getLatestAssetOperationTimeCount());
    assertEquals(10, instance.getSerializedSize());
    assertEquals(42L, latestAssetOperationTimeMap.get("Key").longValue());
    assertEquals(42L, latestAssetOperationTime.get("Key").longValue());
    assertEquals(42L, latestAssetOperationTimeMap2.get("Key").longValue());
    assertSame(account, instance.getDefaultInstanceForType());
    assertArrayEquals(new byte[]{-110, 1, 7, '\n', 3, 'K', 'e', 'y', 16, '*'}, accountCapsule.getData());
  }

