  /**
   * Method under test: {@link AccountCapsule#getAssetIssuedName()}
   */
  @Test
  public void testGetAssetIssuedName() {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    ByteString actualAssetIssuedName = accountCapsule.getAssetIssuedName();

    // Assert
    ByteString byteString = actualAssetIssuedName.EMPTY;
    Descriptors.Descriptor descriptorForType = accountCapsule.getAccountResource().getDescriptorForType();
    assertEquals(byteString, descriptorForType.toProto().getDefaultInstanceForType().getNameBytes());
    DescriptorProtos.FileOptions options = descriptorForType.getFile().getOptions();
    assertEquals(byteString, options.getCsharpNamespaceBytes());
    assertEquals(byteString, options.getObjcClassPrefixBytes());
    assertEquals(byteString, options.getPhpClassPrefixBytes());
    assertEquals(byteString, options.getPhpMetadataNamespaceBytes());
    assertEquals(byteString, options.getPhpNamespaceBytes());
    assertEquals(byteString, options.getRubyPackageBytes());
    assertEquals(byteString, options.getSwiftPrefixBytes());
    assertSame(account, accountCapsule.getInstance());
    assertSame(byteString, accountCapsule.getAccountId());
    assertSame(byteString, accountCapsule.getAccountName());
    assertSame(byteString, accountCapsule.getAddress());
    assertSame(byteString, accountCapsule.getAssetIssuedID());
    assertSame(byteString, actualAssetIssuedName);
  }

  /**
   * Method under test: {@link AccountCapsule#getAssetIssuedName()}
   */
  @Test
  public void testGetAssetIssuedName2() throws UnsupportedEncodingException {
    // Arrange
    DynamicPropertiesStore dynamicPropertiesStore = mock(DynamicPropertiesStore.class);
    when(dynamicPropertiesStore.getActiveDefaultOperations()).thenReturn("AXAXAXAX".getBytes("UTF-8"));
    Protocol.Account account = Protocol.Account.getDefaultInstance();

    AccountCapsule accountCapsule = new AccountCapsule(account);
    accountCapsule.setDefaultWitnessPermission(dynamicPropertiesStore);

    // Act
    ByteString actualAssetIssuedName = accountCapsule.getAssetIssuedName();

    // Assert
    verify(dynamicPropertiesStore).getActiveDefaultOperations();
    Protocol.Account instance = accountCapsule.getInstance();
    List<Descriptors.FieldDescriptor> fields = instance.getDescriptorForType().getFields();
    assertEquals(43, fields.size());
    ByteString byteString = actualAssetIssuedName.EMPTY;
    Descriptors.Descriptor descriptorForType = accountCapsule.getAccountResource().getDescriptorForType();
    assertEquals(byteString, descriptorForType.toProto().getDefaultInstanceForType().getNameBytes());
    DescriptorProtos.FileOptions options = descriptorForType.getFile().getOptions();
    assertEquals(byteString, options.getCsharpNamespaceBytes());
    assertEquals(byteString, options.getObjcClassPrefixBytes());
    assertEquals(byteString, options.getPhpClassPrefixBytes());
    assertEquals(byteString, options.getPhpMetadataNamespaceBytes());
    assertEquals(byteString, options.getPhpNamespaceBytes());
    assertEquals(byteString, options.getRubyPackageBytes());
    assertEquals(byteString, options.getSwiftPrefixBytes());
    assertSame(account, instance.getDefaultInstanceForType());
    assertSame(byteString, fields.get(0).getDefaultValue());
    assertSame(byteString, accountCapsule.getAccountId());
    assertSame(byteString, accountCapsule.getAccountName());
    assertSame(byteString, accountCapsule.getAddress());
    assertSame(byteString, accountCapsule.getAssetIssuedID());
    assertSame(byteString, actualAssetIssuedName);
    assertSame(byteString, instance.getAccountId());
    assertSame(byteString, instance.getAccountName());
    assertSame(byteString, instance.getAddress());
    assertSame(byteString, instance.getAssetIssuedID());
    assertSame(byteString, instance.getAssetIssuedName());
    assertSame(byteString, instance.getCode());
    assertSame(byteString, instance.getCodeHash());
    assertSame(byteString, instance.getOwnerPermission().getOperations());
    assertSame(byteString, instance.getWitnessPermission().getOperations());
  }

