  /**
   * Method under test: {@link AccountCapsule#setFrozenForBandwidth(long, long)}
   */
  @Test
  public void testSetFrozenForBandwidth() {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    accountCapsule.setFrozenForBandwidth(42L, 1L);

    // Assert
    List<Protocol.Account.Frozen> frozenList = accountCapsule.getFrozenList();
    assertEquals(1, frozenList.size());
    Protocol.Account.Frozen getResult = frozenList.get(0);
    assertEquals("", getResult.getInitializationErrorString());
    Protocol.Account instance = accountCapsule.getInstance();
    assertEquals(1, instance.getAllFields().size());
    assertEquals(1, accountCapsule.getFrozenCount());
    assertEquals(1, instance.getFrozenCount());
    assertEquals(1L, getResult.getExpireTime());
    assertEquals(2, getResult.getAllFields().size());
    assertEquals(4, getResult.getSerializedSize());
    assertEquals(42L, accountCapsule.getAllFrozenBalanceForBandwidth());
    assertEquals(42L, accountCapsule.getAllTronPower());
    assertEquals(42L, accountCapsule.getFrozenBalance());
    assertEquals(42L, accountCapsule.getTronPower());
    assertEquals(42L, getResult.getFrozenBalance());
    assertEquals(6, instance.getSerializedSize());
    Protocol.Account.AccountResource accountResource = accountCapsule.getAccountResource();
    Descriptors.Descriptor descriptorForType = accountResource.getDescriptorForType();
    DescriptorProtos.MessageOptions options = descriptorForType.getOptions();
    assertTrue(options.findInitializationErrors().isEmpty());
    DescriptorProtos.DescriptorProto toProtoResult = descriptorForType.toProto();
    assertTrue(toProtoResult.findInitializationErrors().isEmpty());
    assertTrue(getResult.findInitializationErrors().isEmpty());
    assertTrue(accountResource.findInitializationErrors().isEmpty());
    assertTrue(instance.findInitializationErrors().isEmpty());
    Protocol.Permission ownerPermission = instance.getOwnerPermission();
    assertTrue(ownerPermission.findInitializationErrors().isEmpty());
    Protocol.Account.Frozen frozenBalanceForEnergy = accountResource.getFrozenBalanceForEnergy();
    assertTrue(frozenBalanceForEnergy.findInitializationErrors().isEmpty());
    assertTrue(toProtoResult.getReservedNameList().isEmpty());
    assertTrue(descriptorForType.getEnumTypes().isEmpty());
    Descriptors.Descriptor descriptorForType2 = instance.getDescriptorForType();
    assertTrue(descriptorForType2.getEnumTypes().isEmpty());
    Descriptors.Descriptor descriptorForType3 = frozenBalanceForEnergy.getDescriptorForType();
    assertTrue(descriptorForType3.getEnumTypes().isEmpty());
    assertTrue(descriptorForType.getExtensions().isEmpty());
    assertTrue(descriptorForType2.getExtensions().isEmpty());
    assertTrue(descriptorForType3.getExtensions().isEmpty());
    assertTrue(descriptorForType.getNestedTypes().isEmpty());
    assertTrue(descriptorForType3.getNestedTypes().isEmpty());
    assertTrue(descriptorForType.getOneofs().isEmpty());
    assertTrue(descriptorForType2.getOneofs().isEmpty());
    assertTrue(descriptorForType3.getOneofs().isEmpty());
    assertTrue(descriptorForType.getRealOneofs().isEmpty());
    assertTrue(descriptorForType2.getRealOneofs().isEmpty());
    assertTrue(descriptorForType3.getRealOneofs().isEmpty());
    Descriptors.FileDescriptor file = descriptorForType.getFile();
    assertTrue(file.getExtensions().isEmpty());
    assertTrue(file.getPublicDependencies().isEmpty());
    assertTrue(file.getServices().isEmpty());
    List<Protocol.Account.Frozen> frozenSupplyList = accountCapsule.getFrozenSupplyList();
    assertTrue(frozenSupplyList.isEmpty());
    assertTrue(getResult.isInitialized());
    DescriptorProtos.DescriptorProto defaultInstanceForType = toProtoResult.getDefaultInstanceForType();
    assertEquals(frozenSupplyList, defaultInstanceForType.findInitializationErrors());
    assertEquals(frozenSupplyList, options.getFeatures().findInitializationErrors());
    DescriptorProtos.DescriptorProto toProtoResult2 = descriptorForType2.toProto();
    assertEquals(frozenSupplyList, toProtoResult2.findInitializationErrors());
    DescriptorProtos.DescriptorProto toProtoResult3 = descriptorForType3.toProto();
    assertEquals(frozenSupplyList, toProtoResult3.findInitializationErrors());
    DescriptorProtos.FileOptions options2 = file.getOptions();
    assertEquals(frozenSupplyList, options2.findInitializationErrors());
    DescriptorProtos.FileDescriptorProto toProtoResult4 = file.toProto();
    assertEquals(frozenSupplyList, toProtoResult4.findInitializationErrors());
    assertEquals(frozenSupplyList, toProtoResult4.getPublicDependencyList());
    Descriptors.Descriptor descriptorForType4 = options.getDescriptorForType();
    assertEquals(frozenSupplyList, descriptorForType4.getEnumTypes());
    Descriptors.Descriptor descriptorForType5 = toProtoResult.getDescriptorForType();
    assertEquals(frozenSupplyList, descriptorForType5.getEnumTypes());
    assertEquals(frozenSupplyList, descriptorForType4.getExtensions());
    assertEquals(frozenSupplyList, descriptorForType5.getExtensions());
    Descriptors.Descriptor descriptorForType6 = ownerPermission.getDescriptorForType();
    assertEquals(frozenSupplyList, descriptorForType6.getExtensions());
    assertEquals(frozenSupplyList, descriptorForType4.getNestedTypes());
    assertEquals(frozenSupplyList, descriptorForType6.getNestedTypes());
    assertEquals(frozenSupplyList, descriptorForType4.getOneofs());
    assertEquals(frozenSupplyList, descriptorForType5.getOneofs());
    assertEquals(frozenSupplyList, descriptorForType6.getOneofs());
    assertEquals(frozenSupplyList, descriptorForType4.getRealOneofs());
    assertEquals(frozenSupplyList, descriptorForType5.getRealOneofs());
    assertEquals(frozenSupplyList, descriptorForType6.getRealOneofs());
    assertSame(descriptorForType3, getResult.getDescriptorForType());
    assertSame(accountResource, accountResource.getDefaultInstanceForType());
    assertSame(frozenSupplyList, defaultInstanceForType.getEnumTypeList());
    assertSame(frozenSupplyList, toProtoResult.getEnumTypeList());
    assertSame(frozenSupplyList, toProtoResult2.getEnumTypeList());
    assertSame(frozenSupplyList, toProtoResult3.getEnumTypeList());
    assertSame(frozenSupplyList, defaultInstanceForType.getEnumTypeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getEnumTypeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult2.getEnumTypeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getEnumTypeOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getExtensionList());
    assertSame(frozenSupplyList, toProtoResult.getExtensionList());
    assertSame(frozenSupplyList, toProtoResult2.getExtensionList());
    assertSame(frozenSupplyList, toProtoResult3.getExtensionList());
    assertSame(frozenSupplyList, defaultInstanceForType.getExtensionOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getExtensionOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult2.getExtensionOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getExtensionOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getExtensionRangeList());
    assertSame(frozenSupplyList, toProtoResult.getExtensionRangeList());
    assertSame(frozenSupplyList, toProtoResult2.getExtensionRangeList());
    assertSame(frozenSupplyList, toProtoResult3.getExtensionRangeList());
    assertSame(frozenSupplyList, defaultInstanceForType.getExtensionRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getExtensionRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult2.getExtensionRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getExtensionRangeOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getFieldList());
    assertSame(frozenSupplyList, defaultInstanceForType.getFieldOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getNestedTypeList());
    assertSame(frozenSupplyList, toProtoResult.getNestedTypeList());
    assertSame(frozenSupplyList, toProtoResult3.getNestedTypeList());
    assertSame(frozenSupplyList, defaultInstanceForType.getNestedTypeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getNestedTypeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getNestedTypeOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getOneofDeclList());
    assertSame(frozenSupplyList, toProtoResult.getOneofDeclList());
    assertSame(frozenSupplyList, toProtoResult2.getOneofDeclList());
    assertSame(frozenSupplyList, toProtoResult3.getOneofDeclList());
    assertSame(frozenSupplyList, defaultInstanceForType.getOneofDeclOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getOneofDeclOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult2.getOneofDeclOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getOneofDeclOrBuilderList());
    assertSame(frozenSupplyList, defaultInstanceForType.getReservedRangeList());
    assertSame(frozenSupplyList, toProtoResult.getReservedRangeList());
    assertSame(frozenSupplyList, toProtoResult2.getReservedRangeList());
    assertSame(frozenSupplyList, toProtoResult3.getReservedRangeList());
    assertSame(frozenSupplyList, defaultInstanceForType.getReservedRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult.getReservedRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult2.getReservedRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult3.getReservedRangeOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult4.getExtensionList());
    assertSame(frozenSupplyList, toProtoResult4.getExtensionOrBuilderList());
    assertSame(frozenSupplyList, toProtoResult4.getServiceList());
    assertSame(frozenSupplyList, toProtoResult4.getServiceOrBuilderList());
    assertSame(frozenSupplyList, options2.getUninterpretedOptionList());
    assertSame(frozenSupplyList, options2.getUninterpretedOptionOrBuilderList());
    assertSame(frozenSupplyList, options.getUninterpretedOptionList());
    assertSame(frozenSupplyList, options.getUninterpretedOptionOrBuilderList());
    assertSame(frozenSupplyList, accountCapsule.getFrozenV2List());
    assertSame(frozenSupplyList, accountCapsule.getUnfrozenV2List());
    assertSame(frozenSupplyList, accountCapsule.getVotesList());
    assertSame(frozenSupplyList, instance.getActivePermissionList());
    assertSame(frozenSupplyList, instance.getActivePermissionOrBuilderList());
    assertSame(frozenSupplyList, instance.getFrozenSupplyList());
    assertSame(frozenSupplyList, instance.getFrozenSupplyOrBuilderList());
    assertSame(frozenSupplyList, instance.getFrozenV2List());
    assertSame(frozenSupplyList, instance.getFrozenV2OrBuilderList());
    assertSame(frozenSupplyList, instance.getUnfrozenV2List());
    assertSame(frozenSupplyList, instance.getUnfrozenV2OrBuilderList());
    assertSame(frozenSupplyList, instance.getVotesList());
    assertSame(frozenSupplyList, instance.getVotesOrBuilderList());
    assertSame(frozenSupplyList, ownerPermission.getKeysList());
    assertSame(frozenSupplyList, ownerPermission.getKeysOrBuilderList());
    assertSame(ownerPermission, instance.getWitnessPermission());
    assertSame(frozenBalanceForEnergy, getResult.getDefaultInstanceForType());
    assertSame(account, instance.getDefaultInstanceForType());
    assertArrayEquals(new byte[]{':', 4, '\b', '*', 16, 1}, accountCapsule.getData());
  }

