  /**
   * Method under test:
   * {@link AccountCapsule#setNewWindowSize(Common.ResourceCode, long)}
   */
  @Test
  public void testSetNewWindowSize() {
    // Arrange
    Protocol.Account account = Protocol.Account.getDefaultInstance();
    AccountCapsule accountCapsule = new AccountCapsule(account);

    // Act
    accountCapsule.setNewWindowSize(Common.ResourceCode.BANDWIDTH, 3L);

    // Assert
    Protocol.Account.AccountResource accountResource = accountCapsule.getAccountResource();
    assertEquals(0, accountResource.getSerializedSize());
    assertEquals(0L, accountResource.getEnergyWindowSize());
    Protocol.Account instance = accountCapsule.getInstance();
    assertEquals(1, instance.getAllFields().size());
    assertEquals(3, instance.getSerializedSize());
    assertEquals(3L, instance.getNetWindowSize());
    assertFalse(instance.hasAccountResource());
    assertTrue(accountResource.getAllFields().isEmpty());
    assertSame(accountResource, accountResource.getDefaultInstanceForType());
    assertSame(account, instance.getDefaultInstanceForType());
    assertArrayEquals(new byte[]{-64, 1, 3}, accountCapsule.getData());
  }

